function validate([edges]) {
  if (!Array.isArray(edges)) return 'edges must be an array.';
  const n = edges.length;
  if (n < 2 || n > 100000) return 'edges needs 2 to 100000 entries.';
  for (let i = 0; i < n; i++) {
    const v = edges[i];
    if (!Number.isInteger(v) || v < -1 || v >= n) return 'Each edges[i] is -1 or a node index below n.';
    if (v === i) return 'A node cannot point to itself.';
  }
  return null;
}

