function longestCycle(edges) {
  const n = edges.length;
  const visitedAt = new Array(n).fill(0);
  let clock = 1;
  let longest = -1;

  for (let start = 0; start < n; start++) {
    if (visitedAt[start] !== 0) {
      continue;
    }
    const walkStart = clock;
    let node = start;
    while (node !== -1 && visitedAt[node] === 0) {
      visitedAt[node] = clock;
      clock++;
      node = edges[node];
    }
    if (node !== -1 && visitedAt[node] >= walkStart) {
      longest = Math.max(longest, clock - visitedAt[node]);
    }
  }
  return longest;
}

