function longestCycle(edges) {
  const n = edges.length;
  let best = -1;
  for (let i = 0; i < n; i++) {
    let cur = edges[i];
    for (let steps = 1; steps <= n && cur !== -1; steps++) {
      if (cur === i) { best = Math.max(best, steps); break; }
      cur = edges[cur];
    }
  }
  return best;
}

