function generate(rand, size) {
  const n = size === 'large' ? 1500 + Math.floor(rand() * 501) : 2 + Math.floor(rand() * 9);
  const edges = new Array(n).fill(-1);
  const noEdge = rand() * 0.3;
  for (let i = 0; i < n; i++) {
    if (rand() < noEdge) continue;
    let target = Math.floor(rand() * (n - 1));
    if (target >= i) target++;
    edges[i] = target;
  }
  // Sometimes plant one long cycle through a random set of nodes so long answers appear.
  if (rand() < 0.5) {
    const order = Array.from({ length: n }, (_, i) => i);
    for (let i = n - 1; i > 0; i--) {
      const j = Math.floor(rand() * (i + 1));
      [order[i], order[j]] = [order[j], order[i]];
    }
    const length = 2 + Math.floor(rand() * (n - 1));
    for (let k = 0; k < length; k++) edges[order[k]] = order[(k + 1) % length];
  }
  return [edges];
}
